function Toolbar({ search, setSearch, onAdd, onSearch, onRefresh, busy=false, placeholder, actions=null, filter }) { const {t}=useI18n(); return <div className="toolbar"><div className="search-box"><Search size={17}/><input placeholder={placeholder||t("searchProducts")} value={search} onChange={e=>setSearch(e.target.value)} onKeyDown={e=>e.key==="Enter"&&onSearch()}/></div>{filter||null}<button className="primary" onClick={onSearch} disabled={busy}><Search size={16}/>{t("search")}</button><div className="toolbar-spacer"/><button className="outline" onClick={onRefresh} disabled={busy}><RefreshCw size={16}/>{t("refresh")}</button>{onAdd&&<button className="primary" onClick={onAdd} disabled={busy}><Plus size={16}/>{t("add")}</button>}{actions}</div>; }

const quickDateRange=key=>{
  const today=new Date(),dateValue=date=>localDateValue(date),shift=days=>{const date=new Date(today);date.setDate(date.getDate()+days);return date},mondayOffset=(today.getDay()+6)%7;
  if(key==="all")return {startDate:"",endDate:""};
  if(key==="today")return {startDate:dateValue(today),endDate:dateValue(today)};
  if(key==="yesterday"){const date=shift(-1),value=dateValue(date);return {startDate:value,endDate:value}}
  if(key==="last7")return {startDate:dateValue(shift(-6)),endDate:dateValue(today)};
  if(key==="last30")return {startDate:dateValue(shift(-29)),endDate:dateValue(today)};
  if(key==="thisWeek")return {startDate:dateValue(shift(-mondayOffset)),endDate:dateValue(today)};
  if(key==="lastWeek")return {startDate:dateValue(shift(-mondayOffset-7)),endDate:dateValue(shift(-mondayOffset-1))};
  if(key==="thisMonth")return {startDate:dateValue(new Date(today.getFullYear(),today.getMonth(),1)),endDate:dateValue(today)};
  if(key==="lastMonth")return {startDate:dateValue(new Date(today.getFullYear(),today.getMonth()-1,1)),endDate:dateValue(new Date(today.getFullYear(),today.getMonth(),0))};
  if(key==="thisYear")return {startDate:dateValue(new Date(today.getFullYear(),0,1)),endDate:dateValue(today)};
  return {startDate:dateValue(new Date(today.getFullYear()-1,0,1)),endDate:dateValue(new Date(today.getFullYear()-1,11,31))};
};

function DateRangePicker({startDate,endDate,onChange}) {
  const {t,locale}=useI18n(),pickerRef=useRef(null);
  const initialMonth=()=>{const value=endDate||startDate;return value?new Date(`${value}T12:00:00`):new Date()};
  const [calendarMonth,setCalendarMonth]=useState(initialMonth),[selectingStart,setSelectingStart]=useState(true);
  const presets=[["all","allDates"],["today","today"],["yesterday","yesterday"],["last7","last7Days"],["last30","last30Days"],["thisWeek","thisWeek"],["lastWeek","lastWeek"],["thisMonth","thisMonth"],["lastMonth","lastMonth"],["thisYear","thisYear"],["lastYear","lastYear"]];
  useEffect(()=>{const close=event=>{if(pickerRef.current&&!pickerRef.current.contains(event.target))pickerRef.current.removeAttribute("open")};document.addEventListener("pointerdown",close);return()=>document.removeEventListener("pointerdown",close)},[]);
  const label=!startDate&&!endDate?t("allDates"):startDate===endDate?startDate:`${startDate||"…"} — ${endDate||"…"}`;
  const choose=key=>{const range=quickDateRange(key);onChange(range);setSelectingStart(true);if(range.endDate)setCalendarMonth(new Date(`${range.endDate}T12:00:00`));pickerRef.current?.removeAttribute("open")};
  const monthStart=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth(),1),firstOffset=(monthStart.getDay()+6)%7,daysInMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()+1,0).getDate();
  const weekdays=Array.from({length:7},(_,index)=>new Intl.DateTimeFormat(locale,{weekday:"short"}).format(new Date(2024,0,index+1)));
  const calendarDays=Array.from({length:42},(_,index)=>{const day=index-firstOffset+1;return day>=1&&day<=daysInMonth?day:null});
  const selectDay=day=>{const value=localDateValue(new Date(calendarMonth.getFullYear(),calendarMonth.getMonth(),day));if(selectingStart||!startDate){onChange({startDate:value,endDate:""});setSelectingStart(false)}else{onChange(value<startDate?{startDate:value,endDate:startDate}:{startDate,endDate:value});setSelectingStart(true)}};
  const changeMonth=offset=>setCalendarMonth(current=>new Date(current.getFullYear(),current.getMonth()+offset,1));
  const changeManual=range=>{onChange(range);setSelectingStart(Boolean(range.endDate));const value=range.endDate||range.startDate;if(value)setCalendarMonth(new Date(`${value}T12:00:00`))};
  return <details className="date-range-picker" ref={pickerRef} onToggle={event=>{if(event.currentTarget.open){setCalendarMonth(initialMonth());setSelectingStart(true)}}}><summary className="outline" aria-label={t("chooseDateRange")}><CalendarDays size={16}/><span>{label}</span><ChevronDown size={14}/></summary><div className="date-range-menu"><div className="date-range-presets"><b>{t("quickDateRange")}</b>{presets.map(([key,labelKey])=><button type="button" key={key} onClick={()=>choose(key)}>{t(labelKey)}</button>)}</div><div className="date-range-calendars"><b>{t("customDateRange")}</b><div className="range-calendar"><div className="range-calendar-head"><button type="button" className="outline" aria-label={t("previousMonth")} onClick={()=>changeMonth(-1)}><ChevronLeft size={16}/></button><strong>{new Intl.DateTimeFormat(locale,{year:"numeric",month:"long"}).format(monthStart)}</strong><button type="button" className="outline" aria-label={t("nextMonth")} onClick={()=>changeMonth(1)}><ChevronRight size={16}/></button></div><div className="range-calendar-weekdays">{weekdays.map(day=><span key={day}>{day}</span>)}</div><div className="range-calendar-days">{calendarDays.map((day,index)=>{if(!day)return <span key={`empty-${index}`}/>;const value=localDateValue(new Date(calendarMonth.getFullYear(),calendarMonth.getMonth(),day)),selected=value===startDate||value===endDate,inRange=startDate&&endDate&&value>startDate&&value<endDate;return <button type="button" key={value} className={`${selected?"selected":""} ${inRange?"in-range":""}`} onClick={()=>selectDay(day)}>{day}</button>})}</div></div><div className="date-range-inputs"><label>{t("startDate")}<input type="date" value={startDate} max={endDate||undefined} onChange={event=>changeManual({startDate:event.target.value,endDate})}/></label><label>{t("endDate")}<input type="date" value={endDate} min={startDate||undefined} onChange={event=>changeManual({startDate,endDate:event.target.value})}/></label></div><small className="date-range-hint">{t(selectingStart?"selectRangeStart":"selectRangeEnd")}</small></div></div></details>;
}

