const productSortCollator=new Intl.Collator(undefined,{numeric:true,sensitivity:"base"});
function compareProductSortValues(left,right) {
  if(left===right)return 0;
  if(left===null||left===undefined||left==="")return 1;
  if(right===null||right===undefined||right==="")return -1;
  if(typeof left==="number"&&typeof right==="number")return left-right;
  return productSortCollator.compare(String(left),String(right));
}

async function loadProductImageForExcel(imageUrl) {
  const response=await fetch(imageUrl);
  if(!response.ok)throw new Error(`image ${response.status}`);
  const bitmap=await createImageBitmap(await response.blob()),canvas=document.createElement("canvas"),scale=Math.min(1,96/Math.max(bitmap.width,bitmap.height));
  canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext("2d").drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close?.();
  const png=await new Promise((resolve,reject)=>canvas.toBlob(result=>result?resolve(result):reject(new Error("image conversion failed")),"image/png"));
  return {buffer:await png.arrayBuffer(),extension:"png",width:canvas.width,height:canvas.height};
}

