  useEffect(()=>()=>rows.forEach(row=>row.image?.previewUrl&&URL.revokeObjectURL(row.image.previewUrl)),[rows]);
  const downloadTemplate=async()=>{
    const ExcelJS=await loadExcelJs();
    const headers=[t("productImage"),...productSpreadsheetFields.map(field=>t(field.label))];
    const workbook=new ExcelJS.Workbook(),sheet=workbook.addWorksheet(t("products"));sheet.addRow(headers);formatProductWorksheet(sheet,[12,14,16,24,24,22,18,10,12,12,14,14,14,14,12,12]);sheet.getRow(2).height=60;
    const notes=workbook.addWorksheet(t("instructions"));[t("productImportInstructions"),t("productImportImageColumnHelp"),t("productImportImageFormats"),t("productImportRequiredFields"),t("productImportTextFieldTip"),t("productImportCategoryTip"),t("productImportStockTip"),t("productImportPurchaseQuantityTip")].forEach(note=>notes.addRow([note]));notes.getColumn(1).width=88;notes.getColumn(1).alignment={wrapText:true,vertical:"top"};notes.getRow(1).font={bold:true,color:{argb:"FF258DCA"}};
    await downloadWorkbook(workbook,`product-import-template-${localDateValue()}.xlsx`);
  };
