      if(missing.length)throw new Error(`${t("productImportMissingColumns")}：${missing.map(field=>t(field.label)).join("、")}`);
      const parsed=[],validation=[],knownBySku=new Map(products.map(product=>[String(product.sku||"").toLocaleLowerCase(),product])),knownByBarcode=new Map(products.filter(product=>product.barcode).map(product=>[String(product.barcode).toLocaleLowerCase(),product]));
      matrix.slice(1).forEach((source,rowIndex)=>{
        if(source.every(value=>String(value??"").trim()===""))return;
        const row={};
        for(const field of productSpreadsheetFields){const value=indexes[field.key]===undefined?"":source[indexes[field.key]],blank=String(value??"").trim()==="";row[field.key]=field.numeric?Number(blank?(["boxSize","packageSize"].includes(field.key)?1:0):value):String(value??"").trim()}
        row.sourceRow=rowIndex+2;
        const knownBySkuMatch=row.sku?knownBySku.get(row.sku.toLocaleLowerCase()):null,knownByBarcodeMatch=row.barcode?knownByBarcode.get(row.barcode.toLocaleLowerCase()):null;
        if(knownBySkuMatch&&knownByBarcodeMatch&&Number(knownBySkuMatch.id)!==Number(knownByBarcodeMatch.id))validation.push(`${t("rowNumber")} ${row.sourceRow}：${t("productImportIdentityConflict")}`);
        row.existingProductId=(knownBySkuMatch||knownByBarcodeMatch)?.id||null;
        if(!row.existingProductId&&!row.sku)validation.push(`${t("rowNumber")} ${row.sourceRow}：${t("productSku")} ${t("required")}`);
        if(!row.existingProductId&&!row.name)validation.push(`${t("rowNumber")} ${row.sourceRow}：${t("productName")} ${t("required")}`);
        if(!row.existingProductId&&(!Number.isSafeInteger(row.boxSize)||row.boxSize<=0))validation.push(`${t("rowNumber")} ${row.sourceRow}：${t("productImportInvalidBoxSize")}`);
        if(!row.existingProductId&&(!Number.isSafeInteger(row.packageSize)||row.packageSize<=0))validation.push(`${t("rowNumber")} ${row.sourceRow}：${t("productImportInvalidPackageSize")}`);
        if(!row.existingProductId&&[row.cost,row.priceHuf,row.priceEur,row.priceUsd].some(value=>!Number.isFinite(value)||value<0))validation.push(`${t("rowNumber")} ${row.sourceRow}：${t("productImportInvalidPrice")}`);
        if(!Number.isSafeInteger(row.stock))validation.push(`${t("rowNumber")} ${row.sourceRow}：${t("productImportInvalidStock")}`);
        if(!row.existingProductId&&(!Number.isSafeInteger(row.purchaseQuantity)||row.purchaseQuantity<0))validation.push(`${t("rowNumber")} ${row.sourceRow}：${t("productImportInvalidPurchaseQuantity")}`);
        parsed.push(row);
      });
      if(!parsed.length)validation.push(t("productImportEmpty"));
      if(parsed.length>1000)validation.push(t("productImportTooManyRows"));
      parsed.forEach(row=>{if(row.existingProductId)return;const original=row.category,resolved=resolveCategoryPath(original,categories);if(!resolved.valid)validation.push(`${t("rowNumber")} ${row.sourceRow}：${t("productImportUnknownCategory")} ${original}`);else row.category=resolved.name});
