        if(!mimeType||!bytes?.length){validation.push(`${t("rowNumber")} ${rowNumber}：${t("productImportInvalidEmbeddedImage")}`);continue}
        if(bytes.byteLength>5*1024*1024){validation.push(`${t("rowNumber")} ${rowNumber}：${t("productImportImageTooLarge")}`);continue}
        totalImageBytes+=bytes.byteLength;
        const file=new File([bytes],`product-${row.sku||rowNumber}.${extension==="jpeg"?"jpg":"png"}`,{type:mimeType});row.image={file,previewUrl:URL.createObjectURL(file),size:bytes.byteLength};
