  const mainCategories=categories.filter(category=>!category.parentId),subcategories=categories.filter(category=>Number(category.parentId)===Number(mainCategoryId)),selectedCategoryId=subCategoryId||mainCategoryId,selectedCategoryNames=selectedCategoryId?(subCategoryId?subcategories.filter(category=>String(category.id)===String(subCategoryId)).map(category=>category.name):[...mainCategories.filter(category=>String(category.id)===String(mainCategoryId)),...subcategories].map(category=>category.name)):[];
  const filtered=products.filter(p=>(!selectedCategoryNames.length||selectedCategoryNames.includes(p.category))&&(stockFilter==="all"||(stockFilter==="inStock"?p.stock>0:p.stock<=0))&&`${p.sku}${p.barcode}${p.name}${p.name2}${p.category}${p.warehouse}${p.storageLocation}`.toLowerCase().includes(appliedSearch.toLowerCase()));
  const sortValue=(product,key)=>key==="category"?categoryPathLabel(product.category,categories):key==="box"?product.stock/product.boxSize:["createdAt","inboundAt"].includes(key)&&product[key]?new Date(product[key]).getTime():product[key];
  const sorted=sortState?filtered.map((product,index)=>({product,index})).sort((left,right)=>{const comparison=compareProductSortValues(sortValue(left.product,sortState.key),sortValue(right.product,sortState.key));return (sortState.direction==="asc"?comparison:-comparison)||(left.index-right.index)}).map(item=>item.product):filtered;
  const toggleSort=key=>setSortState(current=>current?.key!==key?{key,direction:"asc"}:current.direction==="asc"?{key,direction:"desc"}:null);
  useEffect(()=>setSelectedRowIds(current=>new Set([...current].filter(id=>filtered.some(product=>String(product.id)===id)))),[products,appliedSearch,stockFilter,mainCategoryId,subCategoryId]);
  const save=async(data)=>{if(editor?.id)await onUpdate(editor.id,data);else await onCreate(data);setEditor(null)};
  const openDetail=async product=>{setDetail({id:product.id,sku:product.sku,name:product.name});setDetailLoading(true);setDetailError("");try{setDetail(await onLoadDetail(product.id))}catch(e){setDetailError(e.message)}finally{setDetailLoading(false)}};
  const openProductSales=async product=>{if(!onLoadProductSales)return;setSalesProduct(product);setProductSales([]);setProductSalesLoading(true);setProductSalesError("");try{setProductSales(await onLoadProductSales(product.id))}catch(loadError){setProductSalesError(loadError.message)}finally{setProductSalesLoading(false)}};
