  const normalizedCustomerQuery=customerQuery.trim().toLocaleLowerCase(),compactCustomerQuery=normalizedCustomerQuery.replace(/[\s-]/g,""),customerMatches=normalizedCustomerQuery.length<2?[]:customers.filter(customer=>{const text=[customer.name,customer.phone,customer.taxNumber,customer.vehiclePlate,...(customer.vehiclePlates||[])].filter(Boolean).join(" ").toLocaleLowerCase();return text.includes(normalizedCustomerQuery)||text.replace(/[\s-]/g,"").includes(compactCustomerQuery)}).slice(0,20);
  const selectCustomer=customer=>{setCustomerId(String(customer.id));setCustomerQuery(customer.name);setCustomerOpen(false)};
  const selectedCustomer=customers.find(customer=>String(customer.id)===String(customerId)),discountPercent=Number(selectedCustomer?.groupDiscountPercent||0);
  const addProduct=(p)=>setCart(v=>{const found=v.find(x=>x.id===p.id);return found?v.map(x=>x.id===p.id?{...x,qty:x.qty+1}:x):[...v,{...p,qty:1}]});
  const normalizedProductQuery=query.trim().toLocaleLowerCase(),productMatches=normalizedProductQuery.length<2?[]:products.filter(product=>[product.sku,product.barcode,product.name,product.name2].some(value=>String(value||"").toLocaleLowerCase().includes(normalizedProductQuery))).sort((left,right)=>{const score=product=>{const sku=String(product.sku||"").toLocaleLowerCase(),barcode=String(product.barcode||"").toLocaleLowerCase();if(sku===normalizedProductQuery||barcode===normalizedProductQuery)return 0;if(sku.startsWith(normalizedProductQuery)||barcode.startsWith(normalizedProductQuery))return 1;return 2};return score(left)-score(right)||String(left.sku||"").localeCompare(String(right.sku||""))}).slice(0,30);
  const selectProduct=product=>{addProduct(product);setQuery("");setProductOpen(false)};
  const scan=(e)=>{e.preventDefault();const exact=normalizedProductQuery?products.find(product=>String(product.barcode||"").toLocaleLowerCase()===normalizedProductQuery||String(product.sku||"").toLocaleLowerCase()===normalizedProductQuery):null,product=exact||(productMatches.length===1?productMatches[0]:null);if(product)selectProduct(product);else if(normalizedProductQuery.length>=2)setProductOpen(true)};
