  const hasZeroQuantity=cart.some(item=>item.qty===0);
  const openDeliveryModal=()=>{if(canSave&&cart.length&&!hasZeroQuantity)setDeliveryModal(true)};
  const save=async delivery=>{setSaving(true);setError("");const payload={customerId:customerId?Number(customerId):null,currency,notes:sale?.notes||"",...delivery,items:cart.map(item=>({productId:item.id,quantity:item.qty}))};try{const saved=sale?await onUpdateSale(sale.databaseId,payload):await onSaveSale(payload);setDeliveryModal(false);if(!sale)setCart([]);await onOpenDelivery(saved.databaseId);setToast(t(sale?"orderUpdated":"orderSaved"))}catch(e){setError(`${t(sale?"saleUpdateFailed":"saleSaveFailed")}：${e.message}`)}finally{setSaving(false)}};
  const startNewOrder=()=>{onCloseEdit?.();setQuery("");setProductOpen(false);setCart([]);setCustomerId("");setCustomerQuery("");setCustomerOpen(false);setCurrency(defaultCurrency);setError("");setToast("")};
